task max_sum(s: seq, n: int) returns (r: int)
  requires n >= 0
  requires n <= len(s)
  ensures r == max_bis(s, n)
spec fun max_bis(s: seq, n: int): int
  decreases 0
= if n <= 0 then 0 else if n == 1 then s[0] else max_bis(s, n)
{
  r := 0;
  var i: int := 0;
  var best: int := 0;
  var k: int := 0;
